package projectreport

import (
	"fmt"
	"html/template"
	"io"
)

var reportTemplate = template.Must(template.New("report").Funcs(template.FuncMap{
	"short": func(value string) string {
		if len(value) > 12 {
			return value[:12]
		}
		if value == "" {
			return "not-a-git-snapshot"
		}
		return value
	},
	"n": func(i int) int { return i + 1 },
	// URI is created only after Load has confined the source path to the
	// repository and validated its line range. Marking it here keeps local
	// file navigation usable without accepting profile-provided raw URLs.
	"sourceURL": func(value string) template.URL { return template.URL(value) },
}).Parse(`<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{{.Profile.Name}} · 项目功能与实现</title><style>
:root{--ink:#171816;--muted:#62665f;--paper:#f3f0e8;--panel:#fffef9;--line:#d6d0c3;--green:#146c55;--orange:#d85a32}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.68 system-ui,-apple-system,"PingFang SC",sans-serif}a{color:inherit}.shell{max-width:1260px;margin:auto;padding:24px 28px 80px}.top{display:flex;justify-content:space-between;gap:20px;padding-bottom:18px;border-bottom:1px solid var(--line);font-size:12px}.brand{font-weight:900;letter-spacing:.12em}.fresh{color:var(--green);font-weight:800}.hero{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(300px,.7fr);gap:70px;padding:80px 0 58px}.kicker{color:var(--orange);font-size:11px;font-weight:900;letter-spacing:.16em}.hero h1{margin:12px 0 18px;font:700 clamp(54px,8vw,100px)/.95 Georgia,"Songti SC",serif;letter-spacing:-.055em}.tagline{max-width:800px;font-size:clamp(20px,2.4vw,30px);line-height:1.35}.desc{max-width:780px;color:var(--muted)}.provenance{max-width:780px;padding:12px 14px;border-left:3px solid var(--orange);background:#fff7eb;color:#59493e;font-size:13px}.facts{align-self:end;padding:22px;border-left:4px solid var(--green);background:var(--panel)}.facts dl{display:grid;grid-template-columns:max-content minmax(0,1fr);gap:9px 15px;margin:0}.facts dt{color:var(--muted)}.facts dd{margin:0;overflow-wrap:anywhere}.section{padding:58px 0;border-top:1px solid var(--line)}.section-head{display:grid;grid-template-columns:180px 1fr;gap:30px;margin-bottom:28px}.section h2{margin:0;font:700 clamp(34px,5vw,62px)/1 Georgia,"Songti SC",serif}.intro{max-width:780px;margin:14px 0 0;color:var(--muted)}.highlights,.feature-nav,.judgement-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.highlight,.feature-link,.judgement-card{display:block;padding:22px;border:1px solid var(--line);background:var(--panel);text-decoration:none}.highlight:before{content:"✓";display:block;color:var(--green);font-weight:900;margin-bottom:24px}.feature-link{min-height:190px;transition:.16s ease}.feature-link:hover{transform:translateY(-2px);border-color:var(--green)}.feature-link small{color:var(--orange);font-weight:900}.feature-link h3{margin:28px 0 8px;font-size:21px}.feature-link p{margin:0;color:var(--muted)}.features{display:grid;gap:18px}.feature{scroll-margin-top:18px;border:1px solid var(--line);background:var(--panel)}.feature summary{cursor:pointer;list-style:none;display:grid;grid-template-columns:60px minmax(0,1fr) auto;gap:18px;align-items:center;padding:23px}.feature summary::-webkit-details-marker{display:none}.feature summary b{color:var(--orange);font-size:13px}.feature summary h3{margin:0;font-size:24px}.feature summary span{color:var(--green);font-weight:800}.feature-body{padding:0 24px 28px;border-top:1px solid var(--line)}.provides{font:700 clamp(22px,3vw,34px)/1.35 Georgia,"Songti SC",serif;max-width:900px}.flow{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;margin:25px 0;background:var(--line);border:1px solid var(--line)}.flow div{padding:17px;background:#f7f4ec}.flow small{display:block;color:var(--orange);font-weight:900}.flow b{display:block;margin-top:8px}.mechanism{padding:20px;border-left:4px solid var(--green);background:#edf4ef}.technology{display:flex;flex-wrap:wrap;gap:6px;margin:17px 0}.technology span{padding:5px 9px;border:1px solid var(--line);border-radius:999px;font-size:12px}.reuse-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.reuse-grid div{padding:17px;border:1px solid var(--line)}.reuse-grid small{display:block;color:var(--muted);font-weight:800}.reuse-grid p{margin:8px 0 0}.sources{margin-top:25px}.source{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;padding:14px 0;border-top:1px solid var(--line);text-decoration:none}.source strong,.source span,.source code{display:block;overflow-wrap:anywhere}.source span{color:var(--muted);font-size:12px}.source code{font-size:11px;color:var(--green)}.source-order{color:var(--orange);font-size:11px;font-weight:900}.judgement-card h3{margin-top:0}.judgement-card ul,.questions,.conclusions{padding-left:20px}.reference-fit{margin:18px 0;padding:22px;border-left:4px solid var(--green);background:#edf4ef}.boundary{padding:24px;background:#191d1a;color:#f5f3ea}.boundary p{color:#bfc7c1;margin-bottom:0}footer{padding-top:40px;color:var(--muted);font-size:12px}
@media(max-width:800px){.shell{padding:18px 15px 60px}.hero,.section-head{grid-template-columns:1fr;gap:24px}.hero{padding:50px 0}.highlights,.feature-nav,.judgement-grid{grid-template-columns:1fr 1fr}.flow,.reuse-grid{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.top{align-items:flex-start}.hero h1{font-size:52px}.highlights,.feature-nav,.judgement-grid,.flow,.reuse-grid{grid-template-columns:1fr}.feature summary{grid-template-columns:38px minmax(0,1fr)}.feature summary span{grid-column:2}.source{grid-template-columns:1fr}.facts dl{grid-template-columns:1fr}.facts dd{margin-bottom:8px}}
</style></head><body><main class="shell">
<nav class="top"><span class="brand">REPO TEACHER / PROJECT REPORT</span><span class="fresh">固定源码 {{short .Commit}}{{if .Dirty}} · 工作树有变化{{end}}</span></nav>
<header class="hero"><div><span class="kicker">30 秒看懂这个项目</span><h1>{{.Profile.Name}}</h1><p class="tagline">{{.Profile.Tagline}}</p><p class="desc">{{.Profile.Description}}</p><p class="provenance"><b>内容口径：</b>功能语义来自已审阅的项目 profile；CLI 负责核对源码路径、行范围与内容哈希。本页不是全自动语义抽取结果。</p></div><aside class="facts"><dl><dt>适合谁看</dt><dd>{{.Profile.Audience}}</dd><dt>产品形态</dt><dd>{{.Profile.ProductForm}}</dd><dt>许可证</dt><dd>{{.Profile.License}}</dd><dt>仓库</dt><dd>{{.Profile.Remote}}</dd><dt>本地源码</dt><dd>{{.RepoRoot}}</dd></dl></aside></header>
<section class="section"><div class="section-head"><span class="kicker">先抓重点</span><div><h2>这个项目解决什么问题？</h2><p class="intro">先看产品价值，再看实现。下面不是文件清单，也不替你做跨项目选择。</p></div></div><div class="highlights">{{range .Profile.Highlights}}<article class="highlight">{{.}}</article>{{end}}</div></section>
<section class="section"><div class="section-head"><span class="kicker">功能地图</span><div><h2>它有哪些主要功能？</h2><p class="intro">每张卡先讲“提供什么”。点击后再看数据流、技术、源码与复用边界。</p></div></div><nav class="feature-nav">{{range $i,$f:=.Profile.Features}}<a class="feature-link" href="#feature-{{$f.ID}}"><small>功能 {{n $i}}</small><h3>{{$f.Name}}</h3><p>{{$f.Provides}}</p></a>{{end}}</nav></section>
<section class="section"><div class="section-head"><span class="kicker">逐功能实现</span><div><h2>每个功能是怎么做的？</h2><p class="intro">入口、文件和符号只在这里充当证据。静态源码不能证明的运行时行为会明确写在“仍需验证”。</p></div></div><div class="features">{{range $i,$f:=.Profile.Features}}<details class="feature" id="feature-{{$f.ID}}" {{if eq $i 0}}open{{end}}><summary><b>0{{n $i}}</b><h3>{{$f.Name}}</h3><span>查看实现 ↓</span></summary><div class="feature-body"><p class="provides">{{$f.Provides}}</p><div class="flow"><div><small>谁触发</small><b>{{$f.Trigger}}</b></div><div><small>谁接管</small><b>{{$f.Owner}}</b></div><div><small>输出什么</small><b>{{$f.Output}}</b></div><div><small>谁消费</small><b>{{$f.Consumer}}</b></div></div><div class="mechanism"><b>底层机制</b><p>{{$f.Mechanism}}</p></div><div class="technology">{{range $f.Technologies}}<span>{{.}}</span>{{end}}</div><div class="reuse-grid"><div><small>可直接借鉴</small><p>{{$f.Reuse}}</p></div><div><small>需要改造</small><p>{{$f.Adapt}}</p></div><div><small>不要照搬</small><p>{{$f.Avoid}}</p></div><div><small>仍需验证</small><p>{{$f.Unknown}}</p></div></div><div class="sources"><h4>关键源码证据 · 建议按顺序阅读</h4>{{range $j,$s:=$f.Sources}}<a class="source" href="{{sourceURL $s.URI}}"><div><small class="source-order">阅读 {{n $j}}</small><strong>{{$s.Path}}:{{$s.LineStart}}–{{$s.LineEnd}}{{if $s.Symbol}} · {{$s.Symbol}}{{end}}</strong><span>{{$s.Reason}}</span></div><code>range sha256 {{short $s.SHA256}}</code></a>{{end}}</div></div></details>{{end}}</div></section>
{{if .Profile.ArchitectureSummary}}<section class="section"><div class="section-head"><span class="kicker">项目整体判断</span><div><h2>看完整体，应该怎么理解它？</h2><p class="intro">先收束这个项目自身的架构特征和参考价值，再去读其他项目；这里不做横向排名。</p></div></div><div class="mechanism"><b>架构特征</b><p>{{.Profile.ArchitectureSummary}}</p></div><div class="judgement-grid"><article class="judgement-card"><h3>主要优势</h3><ul>{{range .Profile.Strengths}}<li>{{.}}</li>{{end}}</ul></article><article class="judgement-card"><h3>主要限制</h3><ul>{{range .Profile.Limitations}}<li>{{.}}</li>{{end}}</ul></article><article class="judgement-card"><h3>后续比较要问</h3><ul>{{range .Profile.ComparisonQuestions}}<li>{{.}}</li>{{end}}</ul></article></div><div class="reference-fit"><b>适合作为什么参考</b><p>{{.Profile.ReferenceFit}}</p></div></section>{{end}}
{{if .Profile.Conclusions}}<section class="section"><div class="section-head"><span class="kicker">结束总结</span><div><h2>读完后，记住这几件事</h2><p class="intro">这些结论用于帮助你进入下一个项目，不替你做最后选择。</p></div></div><ol class="conclusions">{{range .Profile.Conclusions}}<li>{{.}}</li>{{end}}</ol></section>{{end}}
<section class="section"><div class="boundary"><b>怎么使用这份报告</b><p>先逐项目理解功能和实现；当你看完多个项目后，再由你决定“哪个功能参考哪个项目”。Repo Teacher 不在本页替你排名，也不把 Star、入口数量或生成文案当作技术结论。</p></div></section>
<footer>Generated {{.GeneratedAt.Format "2006-01-02 15:04 MST"}} · 事实、解释与未知边界分层</footer></main></body></html>`))

func Render(w io.Writer, report Report) error {
	if err := reportTemplate.Execute(w, report); err != nil {
		return fmt.Errorf("render report: %w", err)
	}
	return nil
}
